
//
//  FoodLogView.swift
//  Project Health
//
//  Displays the user's food history from Supabase.
//  Foods are organized by the day they were eaten.
//  Users can select a date, view all dates, refresh,
//  and delete previously logged foods.
//
// Generated by ChatGPT

import SwiftUI


struct FoodLogView: View {

    // Stores the food logs retrieved from Supabase.
    // @State tells SwiftUI to update the screen
    // whenever the array changes.
    @State private var foodLogs: [FoodLog] = []

    // Controls the loading indicator while
    // the app is fetching food logs.
    @State private var isLoading = true

    // Stores an error message if loading or
    // deleting a food log fails.
    @State private var errorMessage = ""

    // Stores the date selected by the user.
    // Date() initializes it to the current date.
    @State private var selectedDate = Date()

    // Determines whether to display all food history.
    // false means only the selected date is displayed.
    @State private var showAllDates = false

    // Gives this view access to the functions in
    // FoodLogService.swift for reading and deleting
    // food logs stored in Supabase.
    private let foodLogService = FoodLogService()


    // MARK: - Group Food Logs By Day

    // Organizes food logs into groups based on the
    // calendar day the food was eaten.
    //
    // The result contains:
    // date = the specific calendar day
    // logs = the foods belonging to that day
    private var foodLogsByDay: [(date: Date, logs: [FoodLog])] {

        // Uses the user's current calendar and time zone.
        let calendar = Calendar.current

        // Dictionary(grouping:) places food entries
        // into groups using the date as the key.
        let groupedLogs = Dictionary(
            grouping: foodLogs
        ) { foodLog in

            // Convert the consumed_at timestamp
            // from Supabase into a Swift Date.
            guard let consumedDate = dateFromConsumedAt(
                foodLog.consumed_at
            ) else {

                // Use a fallback date if the timestamp
                // cannot be converted.
                return Date.distantPast
            }

            // Remove the time portion for grouping.
            //
            // For example:
            // 8:00 AM on Oct 28
            // 6:30 PM on Oct 28
            //
            // Both belong to October 28.
            return calendar.startOfDay(
                for: consumedDate
            )
        }

        // Convert the dictionary into an array
        // and sort the days from newest to oldest.
        return groupedLogs
            .map { date, logs in

                (
                    date: date,

                    // Sort the individual foods within
                    // each day from newest to oldest.
                    logs: logs.sorted {

                        let firstDate = dateFromConsumedAt(
                            $0.consumed_at
                        ) ?? .distantPast

                        let secondDate = dateFromConsumedAt(
                            $1.consumed_at
                        ) ?? .distantPast

                        return firstDate > secondDate
                    }
                )
            }
            .sorted {

                // Show recent days first.
                $0.date > $1.date
            }
    }


    // MARK: - Filter Food Logs By Selected Date

    // Determines which food log groups should
    // actually appear on the screen.
    //
    // This only filters the displayed data.
    // It does not delete or modify Supabase records.
    private var displayedFoodLogsByDay: [(date: Date, logs: [FoodLog])] {

        // When Show All Dates is enabled,
        // display the user's entire food history.
        if showAllDates {
            return foodLogsByDay
        }

        // Otherwise, display only foods belonging
        // to the date selected in the DatePicker.
        return foodLogsByDay.filter { day in

            // Compare the calendar day instead of
            // comparing exact timestamps.
            Calendar.current.isDate(
                day.date,
                inSameDayAs: selectedDate
            )
        }
    }


    // MARK: - Convert Supabase Timestamp To Date

    // Supabase returns consumed_at as an ISO 8601
    // timestamp string, such as:
    //
    // 2026-10-28T12:30:00Z
    //
    // This function converts it into a Swift Date
    // so we can compare and group calendar days.
    private func dateFromConsumedAt(
        _ consumedAt: String
    ) -> Date? {

        let formatter = ISO8601DateFormatter()

        // Try converting a standard ISO 8601 timestamp.
        if let date = formatter.date(
            from: consumedAt
        ) {
            return date
        }

        // Some Supabase timestamps include
        // fractional seconds, such as:
        //
        // 2026-10-28T12:30:00.123Z
        //
        // Try again with fractional seconds enabled.
        formatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]

        // Returns a Date if successful,
        // or nil if conversion fails.
        return formatter.date(
            from: consumedAt
        )
    }


    // MARK: - Format Day Header

    // Creates the date heading for each group.
    //
    // Examples:
    // Today
    // Yesterday
    // October 28, 2026
    private func dayTitle(
        for date: Date
    ) -> String {

        let calendar = Calendar.current

        // Use "Today" for the current calendar day.
        if calendar.isDateInToday(date) {
            return "Today"
        }

        // Use "Yesterday" for the previous day.
        if calendar.isDateInYesterday(date) {
            return "Yesterday"
        }

        // Otherwise, display the full date.
        return date.formatted(
            .dateTime
                .month(.wide)
                .day()
                .year()
        )
    }


    // MARK: - Food Log Interface

    var body: some View {

        // Group switches between loading,
        // error, and normal content states.
        Group {

            // Display a loading indicator while
            // retrieving food logs from Supabase.
            if isLoading {

                ProgressView("Loading food log...")

            } else if !errorMessage.isEmpty {

                // Display an error if a request fails.
                VStack(spacing: 12) {

                    Image(systemName: "exclamationmark.triangle")
                        .font(.largeTitle)

                    Text(errorMessage)
                        .multilineTextAlignment(.center)
                }
                .padding()

            } else {

                // List displays the date selector
                // followed by the food history.
                List {

                    // MARK: - Date Selection

                    Section {

                        // Allows users to choose which
                        // calendar day they want to view.
                        //
                        // $selectedDate creates a binding:
                        // changing the picker updates
                        // selectedDate automatically.
                        DatePicker(
                            "Select Date",
                            selection: $selectedDate,
                            displayedComponents: .date
                        )

                        // Allows users to switch between
                        // their selected day and all dates.
                        //
                        // $showAllDates updates the Boolean
                        // whenever the toggle changes.
                        Toggle(
                            "Show All Dates",
                            isOn: $showAllDates
                        )
                    }


                    // MARK: - Empty Food Log

                    // Show this when the user has not
                    // logged any food at all.
                    if foodLogs.isEmpty {

                        Text("No foods logged yet.")
                            .foregroundColor(.secondary)

                    } else if displayedFoodLogsByDay.isEmpty {

                        // The user has food history,
                        // but nothing for the selected day.
                        Text("No foods logged for this date.")
                            .foregroundColor(.secondary)
                    }


                    // MARK: - Display Foods By Day

                    // Loop through the dates that should
                    // currently appear on screen.
                    //
                    // id: \.date identifies each day
                    // so SwiftUI can track its section.
                    ForEach(
                        displayedFoodLogsByDay,
                        id: \.date
                    ) { day in

                        // Each calendar day gets its
                        // own section in the food list.
                        Section {

                            // Loop through the foods
                            // belonging to this day.
                            ForEach(day.logs) { foodLog in

                                VStack(
                                    alignment: .leading,
                                    spacing: 6
                                ) {

                                    // MARK: Food Name And Calories

                                    HStack {

                                        // Name of the food eaten.
                                        Text(foodLog.food_name)
                                            .font(.headline)

                                        Spacer()

                                        // Calories stored for
                                        // this food log entry.
                                        Text(
                                            "\(foodLog.calories.formatted()) kcal"
                                        )
                                        .fontWeight(.semibold)
                                    }


                                    // MARK: Meal And Serving

                                    HStack {

                                        // Display breakfast, lunch,
                                        // dinner, or snack.
                                        //
                                        // If meal_type is nil,
                                        // display "Meal" instead.
                                        Text(
                                            foodLog.meal_type?
                                                .capitalized ?? "Meal"
                                        )

                                        Spacer()

                                        // Display the amount
                                        // and unit eaten.
                                        Text(
                                            "\(foodLog.serving_amount.formatted()) \(foodLog.serving_unit)"
                                        )
                                    }
                                    .font(.subheadline)
                                    .foregroundColor(.secondary)
                                }


                                // MARK: - Swipe To Delete

                                // Allow the user to swipe left
                                // on a food entry to delete it.
                                .swipeActions(edge: .trailing) {

                                    Button(role: .destructive) {

                                        // Task creates an async
                                        // context so we can await
                                        // the Supabase deletion.
                                        Task {
                                            await deleteFoodLog(foodLog)
                                        }

                                    } label: {

                                        Label(
                                            "Delete",
                                            systemImage: "trash"
                                        )
                                    }
                                }
                            }

                        } header: {

                            // Show Today, Yesterday,
                            // or the actual date.
                            Text(dayTitle(for: day.date))
                        }
                    }
                }

                // Use a simple list appearance.
                .listStyle(.plain)
            }
        }

        // Title displayed in the navigation bar.
        .navigationTitle("Food Log")

        // Automatically load food logs when
        // the view first appears.
        .task {
            await loadFoodLogs()
        }

        // Let the user pull down to retrieve
        // updated food logs from Supabase.
        .refreshable {
            await loadFoodLogs(
                showLoadingIndicator: false
            )
        }
    }


    // MARK: - Load Food Logs From Supabase

    // @MainActor ensures changes to SwiftUI state
    // happen on the main actor.
    //
    // The optional Boolean determines whether
    // we show the full loading indicator.
    @MainActor
    private func loadFoodLogs(
        showLoadingIndicator: Bool = true
    ) async {

        // Only show the full loading screen
        // when the Boolean is true.
        if showLoadingIndicator {
            isLoading = true
        }

        // Clear any old error message.
        errorMessage = ""

        do {

            // Fetch the currently logged-in
            // user's food logs from Supabase.
            //
            // The service already orders them
            // by consumed_at, newest first.
            foodLogs = try await foodLogService.fetchFoodLogs()

        } catch is CancellationError {

            // Handle a cancelled request separately
            // from a regular network/database error.
            print("Food log loading was cancelled.")

        } catch {

            // Show a readable message to the user.
            errorMessage = "Could not load your food log."

            // Print technical details for debugging.
            print(
                "Food log loading failed: \(error.localizedDescription)"
            )
        }

        // Stop the full-screen loading indicator.
        if showLoadingIndicator {
            isLoading = false
        }
    }


    // MARK: - Delete Food Log From Supabase

    // Deletes one food entry using its UUID.
    //
    // After Supabase confirms the deletion,
    // remove the entry from the local array.
    @MainActor
    private func deleteFoodLog(
        _ foodLog: FoodLog
    ) async {

        // Clear any previous error message.
        errorMessage = ""

        do {

            // Delete the record in Supabase.
            try await foodLogService.deleteFoodLog(
                id: foodLog.id
            )

            // Remove the deleted record from
            // the local foodLogs array.
            //
            // Since foodLogs is @State, SwiftUI
            // automatically updates the screen.
            //
            // The date grouping recalculates too.
            foodLogs.removeAll { log in
                log.id == foodLog.id
            }

        } catch {

            // Display a message if deletion fails.
            errorMessage = "Could not delete this food log."

            print(
                "Food log deletion failed: \(error.localizedDescription)"
            )
        }
    }
}
